            if ((mode === 'engrave' || mode === 'doubleshot') && effectiveSvgThickness > maxEngraveDepth) {
                effectiveSvgThickness = maxEngraveDepth;
                console.log("V63.3.1: SVG depth limited to " + effectiveSvgThickness.toFixed(2) + "mm");
            }

